47  static int kvm_sbi_ext_ipi_handler(struct kvm_vcpu *vcpu, struct kvm_run *run, 				   struct kvm_vcpu_sbi_return *retdata)  {
48  	int ret = 0;
49  	unsigned long i;
50  	struct kvm_vcpu *tmp;
51  	struct kvm_cpu_context *cp = &vcpu->arch.guest_context;
52  	unsigned long hmask = cp->a0;
53  	unsigned long hbase = cp->a1;
54  
55  	if (cp->a6 != SBI_EXT_IPI_SEND_IPI) {
56  		retdata->err_val = SBI_ERR_INVALID_PARAM;
57  		return 0;
58  	}
59  
60  	kvm_riscv_vcpu_pmu_incr_fw(vcpu, SBI_PMU_FW_IPI_SENT);
61  	kvm_for_each_vcpu(i, tmp, vcpu->kvm) {
62  		if (hbase != -1UL) {
63  			if (tmp->vcpu_id < hbase)
64  				continue;
65  			if (!(hmask & (1UL << (tmp->vcpu_id - hbase))))
66  				continue;
67  		}
68  		ret = kvm_riscv_vcpu_set_interrupt(tmp, IRQ_VS_SOFT);
69  		if (ret < 0)
70  			break;
71  		kvm_riscv_vcpu_pmu_incr_fw(tmp, SBI_PMU_FW_IPI_RCVD);
72  	}
73  
74  	return ret;
75  }

47  static int kvm_sbi_ext_ipi_handler(struct kvm_vcpu *vcpu, struct kvm_run *run, 				   struct kvm_vcpu_sbi_return *retdata)  {
48  	int ret = 0;
49  	unsigned long i;
50  	struct kvm_vcpu *tmp;
51  	struct kvm_cpu_context *cp = &vcpu->arch.guest_context;
52  	unsigned long hmask = cp->a0;
53  	unsigned long hbase = cp->a1;
54  	unsigned long hart_bit = 0, sentmask = 0;
55  
56  	if (cp->a6 != SBI_EXT_IPI_SEND_IPI) {
57  		retdata->err_val = SBI_ERR_NOT_SUPPORTED;
58  		return 0;
59  	}
60  
61  	kvm_riscv_vcpu_pmu_incr_fw(vcpu, SBI_PMU_FW_IPI_SENT);
62  	kvm_for_each_vcpu(i, tmp, vcpu->kvm) {
63  		if (hbase != -1UL) {
64  			if (tmp->vcpu_id < hbase)
65  				continue;
66  			hart_bit = tmp->vcpu_id - hbase;
67  			if (hart_bit >= __riscv_xlen)
68  				goto done;
69  			if (!(hmask & (1UL << hart_bit)))
70  				continue;
71  		}
72  		ret = kvm_riscv_vcpu_set_interrupt(tmp, IRQ_VS_SOFT);
73  		if (ret < 0)
74  			break;
75  		sentmask |= 1UL << hart_bit;
76  		kvm_riscv_vcpu_pmu_incr_fw(tmp, SBI_PMU_FW_IPI_RCVD);
77  	}
78  
79  done:
80  	if (hbase != -1UL && (hmask ^ sentmask))
81  		retdata->err_val = SBI_ERR_INVALID_PARAM;
82  
83  	return ret;
84  }

428  int kvm_riscv_vcpu_pmu_snapshot_set_shmem(struct kvm_vcpu *vcpu, unsigned long saddr_low, 				      unsigned long saddr_high, unsigned long flags, 				      struct kvm_vcpu_sbi_return *retdata)  {
429  	struct kvm_pmu *kvpmu = vcpu_to_pmu(vcpu);
430  	int snapshot_area_size = sizeof(struct riscv_pmu_snapshot_data);
431  	int sbiret = 0;
432  	gpa_t saddr;
433  
434  	if (!kvpmu || flags) {
435  		sbiret = SBI_ERR_INVALID_PARAM;
436  		goto out;
437  	}
438  
439  	if (saddr_low == SBI_SHMEM_DISABLE && saddr_high == SBI_SHMEM_DISABLE) {
440  		kvm_pmu_clear_snapshot_area(vcpu);
441  		return 0;
442  	}
443  
444  	saddr = saddr_low;
445  
446  	if (saddr_high != 0) {
447  		if (IS_ENABLED(CONFIG_32BIT)) {
448  			saddr |= ((gpa_t)saddr_high << 32);
449  		} else {
450  			sbiret = SBI_ERR_INVALID_ADDRESS;
451  			goto out;
452  		}
453  	}
454  
455  	kvpmu->sdata = kzalloc(snapshot_area_size, GFP_ATOMIC);
456  	if (!kvpmu->sdata)
457  		return -ENOMEM;
458  
459  	/* No need to check writable slot explicitly as kvm_vcpu_write_guest does it internally */
460  	if (kvm_vcpu_write_guest(vcpu, saddr, kvpmu->sdata, snapshot_area_size)) {
461  		kfree(kvpmu->sdata);
462  		kvpmu->sdata = NULL;
463  		sbiret = SBI_ERR_INVALID_ADDRESS;
464  		goto out;
465  	}
466  
467  	kvpmu->snapshot_addr = saddr;
468  
469  out:
470  	retdata->err_val = sbiret;
471  
472  	return 0;
473  }

