284  static int imsic_mrif_isel_check(u32 nr_eix, unsigned long isel)  {
285  	u32 num = 0;
286  
287  	switch (isel) {
288  	case IMSIC_EIDELIVERY:
289  	case IMSIC_EITHRESHOLD:
290  		break;
291  	case IMSIC_EIP0 ... IMSIC_EIP63:
292  		num = isel - IMSIC_EIP0;
293  		break;
294  	case IMSIC_EIE0 ... IMSIC_EIE63:
295  		num = isel - IMSIC_EIE0;
296  		break;
297  	default:
298  		return -ENOENT;
299  	}
300  #ifndef CONFIG_32BIT
301  	if (num & 0x1)
302  		return -EINVAL;
303  #endif
304  	if ((num / 2) >= nr_eix)
305  		return -EINVAL;
306  
307  	return 0;
308  }

