455  int kvm_riscv_vcpu_pmu_event_info(struct kvm_vcpu *vcpu, unsigned long saddr_low, 				  unsigned long saddr_high, unsigned long num_events, 				  unsigned long flags, struct kvm_vcpu_sbi_return *retdata)  {
456  	struct riscv_pmu_event_info *einfo = NULL;
457  	int shmem_size = num_events * sizeof(*einfo);
