473  static void emit_atomic(u8 rd, u8 rs, s16 off, s32 imm, bool is64, 			struct rv_jit_context *ctx)  {
474  	u8 r0;
475  	int jmp_offset;
476  
477  	if (off) {
478  		if (is_12b_int(off)) {
479  			emit_addi(RV_REG_T1, rd, off, ctx);
480  		} else {
481  			emit_imm(RV_REG_T1, off, ctx);
482  			emit_add(RV_REG_T1, RV_REG_T1, rd, ctx);
483  		}
484  		rd = RV_REG_T1;
485  	}
486  
487  	switch (imm) {
488  	/* lock *(u32/u64 *)(dst_reg + off16) <op>= src_reg */
489  	case BPF_ADD:
490  		emit(is64 ? rv_amoadd_d(RV_REG_ZERO, rs, rd, 0, 0) :
491  		     rv_amoadd_w(RV_REG_ZERO, rs, rd, 0, 0), ctx);
492  		break;
493  	case BPF_AND:
494  		emit(is64 ? rv_amoand_d(RV_REG_ZERO, rs, rd, 0, 0) :
495  		     rv_amoand_w(RV_REG_ZERO, rs, rd, 0, 0), ctx);
496  		break;
497  	case BPF_OR:
498  		emit(is64 ? rv_amoor_d(RV_REG_ZERO, rs, rd, 0, 0) :
499  		     rv_amoor_w(RV_REG_ZERO, rs, rd, 0, 0), ctx);
500  		break;
501  	case BPF_XOR:
502  		emit(is64 ? rv_amoxor_d(RV_REG_ZERO, rs, rd, 0, 0) :
503  		     rv_amoxor_w(RV_REG_ZERO, rs, rd, 0, 0), ctx);
504  		break;
505  	/* src_reg = atomic_fetch_<op>(dst_reg + off16, src_reg) */
506  	case BPF_ADD | BPF_FETCH:
507  		emit(is64 ? rv_amoadd_d(rs, rs, rd, 0, 0) :
508  		     rv_amoadd_w(rs, rs, rd, 0, 0), ctx);
509  		if (!is64)
510  			emit_zextw(rs, rs, ctx);
511  		break;
512  	case BPF_AND | BPF_FETCH:
513  		emit(is64 ? rv_amoand_d(rs, rs, rd, 0, 0) :
514  		     rv_amoand_w(rs, rs, rd, 0, 0), ctx);
515  		if (!is64)
516  			emit_zextw(rs, rs, ctx);
517  		break;
518  	case BPF_OR | BPF_FETCH:
519  		emit(is64 ? rv_amoor_d(rs, rs, rd, 0, 0) :
520  		     rv_amoor_w(rs, rs, rd, 0, 0), ctx);
521  		if (!is64)
522  			emit_zextw(rs, rs, ctx);
523  		break;
524  	case BPF_XOR | BPF_FETCH:
525  		emit(is64 ? rv_amoxor_d(rs, rs, rd, 0, 0) :
526  		     rv_amoxor_w(rs, rs, rd, 0, 0), ctx);
527  		if (!is64)
528  			emit_zextw(rs, rs, ctx);
529  		break;
530  	/* src_reg = atomic_xchg(dst_reg + off16, src_reg); */
531  	case BPF_XCHG:
532  		emit(is64 ? rv_amoswap_d(rs, rs, rd, 0, 0) :
533  		     rv_amoswap_w(rs, rs, rd, 0, 0), ctx);
534  		if (!is64)
535  			emit_zextw(rs, rs, ctx);
536  		break;
537  	/* r0 = atomic_cmpxchg(dst_reg + off16, r0, src_reg); */
538  	case BPF_CMPXCHG:
539  		r0 = bpf_to_rv_reg(BPF_REG_0, ctx);
540  		emit(is64 ? rv_addi(RV_REG_T2, r0, 0) :
541  		     rv_addiw(RV_REG_T2, r0, 0), ctx);
542  		emit(is64 ? rv_lr_d(r0, 0, rd, 0, 0) :
543  		     rv_lr_w(r0, 0, rd, 0, 0), ctx);
544  		jmp_offset = ninsns_rvoff(8);
545  		emit(rv_bne(RV_REG_T2, r0, jmp_offset >> 1), ctx);
546  		emit(is64 ? rv_sc_d(RV_REG_T3, rs, rd, 0, 0) :
547  		     rv_sc_w(RV_REG_T3, rs, rd, 0, 0), ctx);
548  		jmp_offset = ninsns_rvoff(-6);
549  		emit(rv_bne(RV_REG_T3, 0, jmp_offset >> 1), ctx);
550  		emit(rv_fence(0x3, 0x3), ctx);
551  		break;
552  	}
553  }

