932  static int has_thead_homogeneous_vlenb(void)  {
933  	int cpu;
934  	u32 prev_vlenb = 0;
935  	u32 vlenb;
936  
937  	/* Ignore thead,vlenb property if xtheavector is not enabled in the kernel */
938  	if (!IS_ENABLED(CONFIG_RISCV_ISA_XTHEADVECTOR))
939  		return 0;
940  
941  	for_each_possible_cpu(cpu) {
942  		struct device_node *cpu_node;
943  
944  		cpu_node = of_cpu_device_node_get(cpu);
945  		if (!cpu_node) {
946  			pr_warn("Unable to find cpu node\n");
947  			return -ENOENT;
948  		}
949  
950  		if (of_property_read_u32(cpu_node, "thead,vlenb", &vlenb)) {
951  			of_node_put(cpu_node);
952  
953  			if (prev_vlenb)
954  				return -ENOENT;
955  			continue;
956  		}
957  
958  		if (prev_vlenb && vlenb != prev_vlenb) {
959  			of_node_put(cpu_node);
960  			return -ENOENT;
961  		}
962  
963  		prev_vlenb = vlenb;
964  		of_node_put(cpu_node);
965  	}
966  
967  	thead_vlenb_of = vlenb;
968  	return 0;
969  }

