 94  static int kvm_sbi_ext_rfence_handler(struct kvm_vcpu *vcpu, struct kvm_run *run, 				      struct kvm_vcpu_sbi_return *retdata)  {
 95  	struct kvm_cpu_context *cp = &vcpu->arch.guest_context;
 96  	unsigned long hmask = cp->a0;
 97  	unsigned long hbase = cp->a1;
 98  	unsigned long funcid = cp->a6;
 99  
100  	switch (funcid) {
101  	case SBI_EXT_RFENCE_REMOTE_FENCE_I:
102  		kvm_riscv_fence_i(vcpu->kvm, hbase, hmask);
103  		kvm_riscv_vcpu_pmu_incr_fw(vcpu, SBI_PMU_FW_FENCE_I_SENT);
104  		break;
105  	case SBI_EXT_RFENCE_REMOTE_SFENCE_VMA:
106  		if ((cp->a2 == 0 && cp->a3 == 0) || cp->a3 == -1UL)
107  			kvm_riscv_hfence_vvma_all(vcpu->kvm, hbase, hmask);
108  		else
109  			kvm_riscv_hfence_vvma_gva(vcpu->kvm, hbase, hmask,
110  						  cp->a2, cp->a3, PAGE_SHIFT);
111  		kvm_riscv_vcpu_pmu_incr_fw(vcpu, SBI_PMU_FW_HFENCE_VVMA_SENT);
112  		break;
113  	case SBI_EXT_RFENCE_REMOTE_SFENCE_VMA_ASID:
114  		if ((cp->a2 == 0 && cp->a3 == 0) || cp->a3 == -1UL)
115  			kvm_riscv_hfence_vvma_asid_all(vcpu->kvm,
116  						       hbase, hmask, cp->a4);
117  		else
118  			kvm_riscv_hfence_vvma_asid_gva(vcpu->kvm,
119  						       hbase, hmask,
120  						       cp->a2, cp->a3,
121  						       PAGE_SHIFT, cp->a4);
122  		kvm_riscv_vcpu_pmu_incr_fw(vcpu, SBI_PMU_FW_HFENCE_VVMA_ASID_SENT);
123  		break;
124  	case SBI_EXT_RFENCE_REMOTE_HFENCE_GVMA:
125  	case SBI_EXT_RFENCE_REMOTE_HFENCE_GVMA_VMID:
126  	case SBI_EXT_RFENCE_REMOTE_HFENCE_VVMA:
127  	case SBI_EXT_RFENCE_REMOTE_HFENCE_VVMA_ASID:
128  		/*
129  		 * Until nested virtualization is implemented, the
130  		 * SBI HFENCE calls should be treated as NOPs
131  		 */
132  		break;
133  	default:
134  		retdata->err_val = SBI_ERR_NOT_SUPPORTED;
135  	}
136  
137  	return 0;
138  }

