425  int kvm_riscv_vcpu_pmu_snapshot_set_shmem(struct kvm_vcpu *vcpu, unsigned long saddr_low, 				      unsigned long saddr_high, unsigned long flags, 				      struct kvm_vcpu_sbi_return *retdata)  {
426  	struct kvm_pmu *kvpmu = vcpu_to_pmu(vcpu);
427  	int snapshot_area_size = sizeof(struct riscv_pmu_snapshot_data);
428  	int sbiret = 0;
429  	gpa_t saddr;
430  
431  	if (!kvpmu || flags) {
432  		sbiret = SBI_ERR_INVALID_PARAM;
433  		goto out;
434  	}
435  
436  	if (saddr_low == SBI_SHMEM_DISABLE && saddr_high == SBI_SHMEM_DISABLE) {
437  		kvm_pmu_clear_snapshot_area(vcpu);
438  		return 0;
439  	}
440  
441  	saddr = saddr_low;
442  
443  	if (saddr_high != 0) {
444  		if (IS_ENABLED(CONFIG_32BIT)) {
445  			saddr |= ((gpa_t)saddr_high << 32);
446  		} else {
447  			sbiret = SBI_ERR_INVALID_ADDRESS;
448  			goto out;
449  		}
450  	}
451  
452  	kvpmu->sdata = kzalloc(snapshot_area_size, GFP_ATOMIC);
453  	if (!kvpmu->sdata)
454  		return -ENOMEM;
455  
456  	/* No need to check writable slot explicitly as kvm_vcpu_write_guest does it internally */
457  	if (kvm_vcpu_write_guest(vcpu, saddr, kvpmu->sdata, snapshot_area_size)) {
458  		kfree(kvpmu->sdata);
459  		kvpmu->sdata = NULL;
460  		sbiret = SBI_ERR_INVALID_ADDRESS;
461  		goto out;
462  	}
463  
464  	kvpmu->snapshot_addr = saddr;
465  
466  out:
467  	retdata->err_val = sbiret;
468  
469  	return 0;
470  }

