225  void bpf_jit_free(struct bpf_prog *prog)  {
226  	if (prog->jited) {
227  		struct rv_jit_data *jit_data = prog->aux->jit_data;
228  		struct bpf_binary_header *hdr;
229  
230  		/*
231  		 * If we fail the final pass of JIT (from jit_subprogs),
232  		 * the program may not be finalized yet. Call finalize here
233  		 * before freeing it.
234  		 */
235  		if (jit_data) {
236  			bpf_jit_binary_pack_finalize(jit_data->ro_header, jit_data->header);
237  			kfree(jit_data);
238  		}
239  		hdr = bpf_jit_binary_pack_hdr(prog);
240  		bpf_jit_binary_pack_free(hdr, NULL);
241  		WARN_ON_ONCE(!bpf_prog_kallsyms_verify_off(prog));
242  	}
243  
244  	bpf_prog_unlock_free(prog);
245  }

