129  static void aplic_write_pending(struct aplic *aplic, u32 irq, bool pending)  {
130  	unsigned long flags, sm;
131  	struct aplic_irq *irqd;
132  
133  	if (!irq || aplic->nr_irqs <= irq)
134  		return;
135  	irqd = &aplic->irqs[irq];
136  
137  	raw_spin_lock_irqsave(&irqd->lock, flags);
138  
139  	sm = irqd->sourcecfg & APLIC_SOURCECFG_SM_MASK;
140  	if (sm == APLIC_SOURCECFG_SM_INACTIVE)
141  		goto skip_write_pending;
142  
143  	if (sm == APLIC_SOURCECFG_SM_LEVEL_HIGH ||
144  	    sm == APLIC_SOURCECFG_SM_LEVEL_LOW) {
145  		if (!pending)
146  			goto noskip_write_pending;
147  		if ((irqd->state & APLIC_IRQ_STATE_INPUT) &&
148  		    sm == APLIC_SOURCECFG_SM_LEVEL_LOW)
149  			goto skip_write_pending;
150  		if (!(irqd->state & APLIC_IRQ_STATE_INPUT) &&
151  		    sm == APLIC_SOURCECFG_SM_LEVEL_HIGH)
152  			goto skip_write_pending;
153  	}
154  
155  noskip_write_pending:
156  	if (pending)
157  		irqd->state |= APLIC_IRQ_STATE_PENDING;
158  	else
159  		irqd->state &= ~APLIC_IRQ_STATE_PENDING;
160  
161  skip_write_pending:
162  	raw_spin_unlock_irqrestore(&irqd->lock, flags);
163  }

316  asmlinkage __visible __trap_section  __no_stack_protector void do_trap_ecall_u(struct pt_regs *regs)  {
317  	if (user_mode(regs)) {
318  		long syscall = regs->a7;
319  
320  		regs->epc += 4;
321  		regs->orig_a0 = regs->a0;
322  
323  		riscv_v_vstate_discard(regs);
324  
325  		syscall = syscall_enter_from_user_mode(regs, syscall);
326  
327  		add_random_kstack_offset();
328  
329  		if (syscall >= 0 && syscall < NR_syscalls)
330  			syscall_handler(regs, syscall);
331  		else if (syscall != -1)
332  			regs->a0 = -ENOSYS;
333  		/*
334  		 * Ultimately, this value will get limited by KSTACK_OFFSET_MAX(),
335  		 * so the maximum stack offset is 1k bytes (10 bits).
336  		 *
337  		 * The actual entropy will be further reduced by the compiler when
338  		 * applying stack alignment constraints: 16-byte (i.e. 4-bit) aligned
339  		 * for RV32I or RV64I.
340  		 *
341  		 * The resulting 6 bits of entropy is seen in SP[9:4].
342  		 */
343  		choose_random_kstack_offset(get_random_u16());
344  
345  		syscall_exit_to_user_mode(regs);
346  	} else {
347  		irqentry_state_t state = irqentry_nmi_enter(regs);
348  
349  		do_trap_error(regs, SIGILL, ILL_ILLTRP, regs->epc,
350  			"Oops - environment call from U-mode");
351  
352  		irqentry_nmi_exit(regs, state);
353  	}
354  
355  }

