681  bool kvm_riscv_vcpu_aia_imsic_has_interrupt(struct kvm_vcpu *vcpu)  {
682  	struct imsic *imsic = vcpu->arch.aia_context.imsic_state;
683  	unsigned long flags;
684  	bool ret = false;
685  
686  	/*
687  	 * The IMSIC SW-file directly injects interrupt via hvip so
688  	 * only check for interrupt when IMSIC VS-file is being used.
689  	 */
690  
691  	read_lock_irqsave(&imsic->vsfile_lock, flags);
692  	if (imsic->vsfile_cpu > -1)
693  		ret = !!(csr_read(CSR_HGEIP) & BIT(imsic->vsfile_hgei));
694  	read_unlock_irqrestore(&imsic->vsfile_lock, flags);
695  
696  	return ret;
697  }

681  bool kvm_riscv_vcpu_aia_imsic_has_interrupt(struct kvm_vcpu *vcpu)  {
682  	struct imsic *imsic = vcpu->arch.aia_context.imsic_state;
683  	unsigned long flags;
684  	bool ret = false;
685  
686  	/*
687  	 * The IMSIC SW-file directly injects interrupt via hvip so
688  	 * only check for interrupt when IMSIC VS-file is being used.
689  	 */
690  
691  	read_lock_irqsave(&imsic->vsfile_lock, flags);
692  	if (imsic->vsfile_cpu > -1) {
693  		/*
694  		 * This function is typically called from kvm_vcpu_block() via
695  		 * kvm_arch_vcpu_runnable() upon WFI trap. The kvm_vcpu_block()
696  		 * can be preempted and the blocking VCPU might resume on a
697  		 * different CPU. This means it is possible that current CPU
698  		 * does not match the imsic->vsfile_cpu hence this function
699  		 * must check imsic->vsfile_cpu before accessing HGEIP CSR.
700  		 */
701  		if (imsic->vsfile_cpu != vcpu->cpu)
702  			ret = true;
703  		else
704  			ret = !!(csr_read(CSR_HGEIP) & BIT(imsic->vsfile_hgei));
705  	}
706  	read_unlock_irqrestore(&imsic->vsfile_lock, flags);
707  
708  	return ret;
709  }

172  int kvm_arch_prepare_memory_region(struct kvm *kvm, 				const struct kvm_memory_slot *old, 				struct kvm_memory_slot *new, 				enum kvm_mr_change change)  {
173  	hva_t hva, reg_end, size;
174  	gpa_t base_gpa;
175  	bool writable;
176  	int ret = 0;
177  
178  	if (change != KVM_MR_CREATE && change != KVM_MR_MOVE &&
179  			change != KVM_MR_FLAGS_ONLY)
180  		return 0;
181  
182  	/*
183  	 * Prevent userspace from creating a memory region outside of the GPA
184  	 * space addressable by the KVM guest GPA space.
185  	 */
186  	if ((new->base_gfn + new->npages) >=
187  	    (kvm_riscv_gstage_gpa_size >> PAGE_SHIFT))
188  		return -EFAULT;
189  
190  	hva = new->userspace_addr;
191  	size = new->npages << PAGE_SHIFT;
192  	reg_end = hva + size;
193  	base_gpa = new->base_gfn << PAGE_SHIFT;
194  	writable = !(new->flags & KVM_MEM_READONLY);
195  
196  	mmap_read_lock(current->mm);
197  
198  	/*
199  	 * A memory region could potentially cover multiple VMAs, and
200  	 * any holes between them, so iterate over all of them to find
201  	 * out if we can map any of them right now.
202  	 *
203  	 *     +--------------------------------------------+
204  	 * +---------------+----------------+   +----------------+
205  	 * |   : VMA 1     |      VMA 2     |   |    VMA 3  :    |
206  	 * +---------------+----------------+   +----------------+
207  	 *     |               memory region                |
208  	 *     +--------------------------------------------+
209  	 */
210  	do {
211  		struct vm_area_struct *vma;
212  		hva_t vm_start, vm_end;
213  
214  		vma = find_vma_intersection(current->mm, hva, reg_end);
215  		if (!vma)
216  			break;
217  
218  		/*
219  		 * Mapping a read-only VMA is only allowed if the
220  		 * memory region is configured as read-only.
221  		 */
222  		if (writable && !(vma->vm_flags & VM_WRITE)) {
223  			ret = -EPERM;
224  			break;
225  		}
226  
227  		/* Take the intersection of this VMA with the memory region */
228  		vm_start = max(hva, vma->vm_start);
229  		vm_end = min(reg_end, vma->vm_end);
230  
231  		if (vma->vm_flags & VM_PFNMAP) {
232  			gpa_t gpa = base_gpa + (vm_start - hva);
233  			phys_addr_t pa;
234  
235  			pa = (phys_addr_t)vma->vm_pgoff << PAGE_SHIFT;
236  			pa += vm_start - vma->vm_start;
237  
238  			/* IO region dirty page logging not allowed */
239  			if (new->flags & KVM_MEM_LOG_DIRTY_PAGES) {
240  				ret = -EINVAL;
241  				goto out;
242  			}
243  
244  			ret = kvm_riscv_mmu_ioremap(kvm, gpa, pa, vm_end - vm_start,
245  						    writable, false);
246  			if (ret)
247  				break;
248  		}
249  		hva = vm_end;
250  	} while (hva < reg_end);
251  
252  	if (change == KVM_MR_FLAGS_ONLY)
253  		goto out;
254  
255  	if (ret)
256  		kvm_riscv_mmu_iounmap(kvm, base_gpa, size);
257  
258  out:
259  	mmap_read_unlock(current->mm);
260  	return ret;
261  }

