201  	 * +---------------+----------------+   +----------------+
202  	 * |   : VMA 1     |      VMA 2     |   |    VMA 3  :    |
203  	 * +---------------+----------------+   +----------------+
204  	 *     |               memory region                |
205  	 *     +--------------------------------------------+
206  	 */
207  	do {
208  		struct vm_area_struct *vma;
209  		hva_t vm_end;
210  
211  		vma = find_vma_intersection(current->mm, hva, reg_end);
212  		if (!vma)
213  			break;
214  
215  		/*
216  		 * Mapping a read-only VMA is only allowed if the
217  		 * memory region is configured as read-only.
218  		 */
219  		if (writable && !(vma->vm_flags & VM_WRITE)) {
220  			ret = -EPERM;
221  			break;
222  		}
223  
224  		/* Take the intersection of this VMA with the memory region */
225  		vm_end = min(reg_end, vma->vm_end);
226  
227  		if (vma->vm_flags & VM_PFNMAP) {
228  			/* IO region dirty page logging not allowed */
229  			if (new->flags & KVM_MEM_LOG_DIRTY_PAGES) {
230  				ret = -EINVAL;
231  				goto out;
232  			}
233  		}
234  		hva = vm_end;
235  	} while (hva < reg_end);
236  
237  out:
238  	mmap_read_unlock(current->mm);
239  	return ret;
240  }

