199  static bool aplic_read_input(struct aplic *aplic, u32 irq)  {
200  	bool ret;
201  	unsigned long flags;
202  	struct aplic_irq *irqd;
203  
204  	if (!irq || aplic->nr_irqs <= irq)
205  		return false;
206  	irqd = &aplic->irqs[irq];
207  
208  	raw_spin_lock_irqsave(&irqd->lock, flags);
