199  static bool aplic_read_input(struct aplic *aplic, u32 irq)  {
200  	u32 sourcecfg, sm, raw_input, irq_inverted;
201  	struct aplic_irq *irqd;
202  	unsigned long flags;
203  	bool ret = false;
204  
205  	if (!irq || aplic->nr_irqs <= irq)
206  		return false;
207  	irqd = &aplic->irqs[irq];
208  
209  	raw_spin_lock_irqsave(&irqd->lock, flags);
210  
211  	sourcecfg = irqd->sourcecfg;
212  	if (sourcecfg & APLIC_SOURCECFG_D)
213  		goto skip;
214  
215  	sm = sourcecfg & APLIC_SOURCECFG_SM_MASK;
216  	if (sm == APLIC_SOURCECFG_SM_INACTIVE)
217  		goto skip;
218  
219  	raw_input = (irqd->state & APLIC_IRQ_STATE_INPUT) ? 1 : 0;
220  	irq_inverted = (sm == APLIC_SOURCECFG_SM_LEVEL_LOW ||
221  			sm == APLIC_SOURCECFG_SM_EDGE_FALL) ? 1 : 0;
222  	ret = !!(raw_input ^ irq_inverted);
223  
224  skip:
225  	raw_spin_unlock_irqrestore(&irqd->lock, flags);
226  
227  	return ret;
228  }

212  static void __init setup_bootmem(void)  {
213  	phys_addr_t vmlinux_end = __pa_symbol(&_end);
214  	phys_addr_t max_mapped_addr;
215  	phys_addr_t phys_ram_end, vmlinux_start;
216  
217  	if (IS_ENABLED(CONFIG_XIP_KERNEL))
218  		vmlinux_start = __pa_symbol(&_sdata);
219  	else
220  		vmlinux_start = __pa_symbol(&_start);
221  
222  	memblock_enforce_memory_limit(memory_limit);
223  
224  	/*
225  	 * Make sure we align the reservation on PMD_SIZE since we will
226  	 * map the kernel in the linear mapping as read-only: we do not want
227  	 * any allocation to happen between _end and the next pmd aligned page.
228  	 */
229  	if (IS_ENABLED(CONFIG_64BIT) && IS_ENABLED(CONFIG_STRICT_KERNEL_RWX))
230  		vmlinux_end = (vmlinux_end + PMD_SIZE - 1) & PMD_MASK;
231  	/*
232  	 * Reserve from the start of the kernel to the end of the kernel
233  	 */
234  	memblock_reserve(vmlinux_start, vmlinux_end - vmlinux_start);
235  
236  	phys_ram_end = memblock_end_of_DRAM();
237  
238  	/*
239  	 * Make sure we align the start of the memory on a PMD boundary so that
240  	 * at worst, we map the linear mapping with PMD mappings.
241  	 */
242  	if (!IS_ENABLED(CONFIG_XIP_KERNEL))
243  		phys_ram_base = memblock_start_of_DRAM() & PMD_MASK;
244  
245  	/*
246  	 * In 64-bit, any use of __va/__pa before this point is wrong as we
247  	 * did not know the start of DRAM before.
248  	 */
249  	if (IS_ENABLED(CONFIG_64BIT) && IS_ENABLED(CONFIG_MMU))
250  		kernel_map.va_pa_offset = PAGE_OFFSET - phys_ram_base;
251  
252  	/*
253  	 * memblock allocator is not aware of the fact that last 4K bytes of
254  	 * the addressable memory can not be mapped because of IS_ERR_VALUE
255  	 * macro. Make sure that last 4k bytes are not usable by memblock
256  	 * if end of dram is equal to maximum addressable memory.  For 64-bit
257  	 * kernel, this problem can't happen here as the end of the virtual
258  	 * address space is occupied by the kernel mapping then this check must
259  	 * be done as soon as the kernel mapping base address is determined.
260  	 */
261  	if (!IS_ENABLED(CONFIG_64BIT)) {
262  		max_mapped_addr = __pa(~(ulong)0);
263  		if (max_mapped_addr == (phys_ram_end - 1))
264  			memblock_set_current_limit(max_mapped_addr - 4096);
265  	}
266  
267  	min_low_pfn = PFN_UP(phys_ram_base);
268  	max_low_pfn = max_pfn = PFN_DOWN(phys_ram_end);
269  	high_memory = (void *)(__va(PFN_PHYS(max_low_pfn)));
270  
271  	dma32_phys_limit = min(4UL * SZ_1G, (unsigned long)PFN_PHYS(max_low_pfn));
272  	set_max_mapnr(max_low_pfn - ARCH_PFN_OFFSET);
273  
274  	reserve_initrd_mem();
275  
276  	/*
277  	 * No allocation should be done before reserving the memory as defined
278  	 * in the device tree, otherwise the allocation could end up in a
279  	 * reserved region.
280  	 */
281  	early_init_fdt_scan_reserved_mem();
282  
283  	/*
284  	 * If DTB is built in, no need to reserve its memblock.
285  	 * Otherwise, do reserve it but avoid using
286  	 * early_init_fdt_reserve_self() since __pa() does
287  	 * not work for DTB pointers that are fixmap addresses
288  	 */
289  	if (!IS_ENABLED(CONFIG_BUILTIN_DTB))
290  		memblock_reserve(dtb_early_pa, fdt_totalsize(dtb_early_va));
291  
292  	dma_contiguous_reserve(dma32_phys_limit);
293  	if (IS_ENABLED(CONFIG_64BIT))
294  		hugetlb_cma_reserve(PUD_SHIFT - PAGE_SHIFT);
295  }

