40  int kvm_riscv_mmu_ioremap(struct kvm *kvm, gpa_t gpa, phys_addr_t hpa, 			  unsigned long size, bool writable, bool in_atomic)  {
41  	int ret = 0;
42  	unsigned long pfn;
43  	phys_addr_t addr, end;
44  	struct kvm_mmu_memory_cache pcache = {
45  		.gfp_custom = (in_atomic) ? GFP_ATOMIC | __GFP_ACCOUNT : 0,
46  		.gfp_zero = __GFP_ZERO,
47  	};
48  	struct kvm_gstage_mapping map;
49  	struct kvm_gstage gstage;
50  
51  	gstage.kvm = kvm;
52  	gstage.flags = 0;
53  	gstage.vmid = READ_ONCE(kvm->arch.vmid.vmid);
54  	gstage.pgd = kvm->arch.pgd;
55  
56  	end = (gpa + size + PAGE_SIZE - 1) & PAGE_MASK;
57  	pfn = __phys_to_pfn(hpa);
58  
59  	for (addr = gpa; addr < end; addr += PAGE_SIZE) {
60  		map.addr = addr;
61  		map.pte = pfn_pte(pfn, PAGE_KERNEL_IO);
62  		map.level = 0;
63  
64  		if (!writable)
65  			map.pte = pte_wrprotect(map.pte);
66  
67  		ret = kvm_mmu_topup_memory_cache(&pcache, kvm_riscv_gstage_pgd_levels);
68  		if (ret)
69  			goto out;
70  
71  		spin_lock(&kvm->mmu_lock);
72  		ret = kvm_riscv_gstage_set_pte(&gstage, &pcache, &map);
73  		spin_unlock(&kvm->mmu_lock);
74  		if (ret)
75  			goto out;
76  
77  		pfn++;
78  	}
79  
80  out:
81  	kvm_mmu_free_memory_cache(&pcache);
82  	return ret;
83  }

