940  int kvm_riscv_aia_imsic_rw_attr(struct kvm *kvm, unsigned long type, 				bool write, unsigned long *val)  {
941  	u32 isel, vcpu_id;
942  	unsigned long flags;
943  	struct imsic *imsic;
944  	struct kvm_vcpu *vcpu;
945  	int rc, vsfile_hgei, vsfile_cpu;
946  
947  	if (!kvm_riscv_aia_initialized(kvm))
948  		return -ENODEV;
949  
950  	vcpu_id = KVM_DEV_RISCV_AIA_IMSIC_GET_VCPU(type);
951  	vcpu = kvm_get_vcpu_by_id(kvm, vcpu_id);
952  	if (!vcpu)
953  		return -ENODEV;
954  
955  	isel = KVM_DEV_RISCV_AIA_IMSIC_GET_ISEL(type);
956  	imsic = vcpu->arch.aia_context.imsic_state;
957  
958  	read_lock_irqsave(&imsic->vsfile_lock, flags);
959  
960  	rc = 0;
961  	vsfile_hgei = imsic->vsfile_hgei;
962  	vsfile_cpu = imsic->vsfile_cpu;
963  	if (vsfile_cpu < 0) {
964  		if (write) {
965  			rc = imsic_mrif_rmw(imsic->swfile, imsic->nr_eix,
966  					    isel, NULL, *val, -1UL);
967  			imsic_swfile_extirq_update(vcpu);
968  		} else
969  			rc = imsic_mrif_rmw(imsic->swfile, imsic->nr_eix,
970  					    isel, val, 0, 0);
971  	}
972  
973  	read_unlock_irqrestore(&imsic->vsfile_lock, flags);
974  
975  	if (!rc && vsfile_cpu >= 0)
976  		rc = imsic_vsfile_rw(vsfile_hgei, vsfile_cpu, imsic->nr_eix,
977  				     isel, write, val);
978  
979  	return rc;
980  }

