451  int kvm_riscv_mmu_map(struct kvm_vcpu *vcpu, struct kvm_memory_slot *memslot, 		      gpa_t gpa, unsigned long hva, bool is_write, 		      struct kvm_gstage_mapping *out_map)  {
452  	int ret;
453  	kvm_pfn_t hfn;
454  	bool writable;
455  	short vma_pageshift;
456  	gfn_t gfn = gpa >> PAGE_SHIFT;
457  	struct vm_area_struct *vma;
458  	struct kvm *kvm = vcpu->kvm;
459  	struct kvm_mmu_memory_cache *pcache = &vcpu->arch.mmu_page_cache;
460  	bool logging = (memslot->dirty_bitmap &&
461  			!(memslot->flags & KVM_MEM_READONLY)) ? true : false;
462  	unsigned long vma_pagesize, mmu_seq;
463  	struct kvm_gstage gstage;
464  	struct page *page;
465  
466  	gstage.kvm = kvm;
467  	gstage.flags = 0;
468  	gstage.vmid = READ_ONCE(kvm->arch.vmid.vmid);
469  	gstage.pgd = kvm->arch.pgd;
470  
471  	/* Setup initial state of output mapping */
472  	memset(out_map, 0, sizeof(*out_map));
473  
474  	/* We need minimum second+third level pages */
475  	ret = kvm_mmu_topup_memory_cache(pcache, kvm_riscv_gstage_pgd_levels);
476  	if (ret) {
477  		kvm_err("Failed to topup G-stage cache\n");
478  		return ret;
479  	}
480  
481  	mmap_read_lock(current->mm);
482  
483  	vma = vma_lookup(current->mm, hva);
484  	if (unlikely(!vma)) {
485  		kvm_err("Failed to find VMA for hva 0x%lx\n", hva);
486  		mmap_read_unlock(current->mm);
487  		return -EFAULT;
488  	}
489  
490  	if (is_vm_hugetlb_page(vma))
491  		vma_pageshift = huge_page_shift(hstate_vma(vma));
492  	else
493  		vma_pageshift = PAGE_SHIFT;
494  	vma_pagesize = 1ULL << vma_pageshift;
495  	if (logging || (vma->vm_flags & VM_PFNMAP))
496  		vma_pagesize = PAGE_SIZE;
497  
498  	if (vma_pagesize == PMD_SIZE || vma_pagesize == PUD_SIZE)
499  		gfn = (gpa & huge_page_mask(hstate_vma(vma))) >> PAGE_SHIFT;
500  
501  	/*
502  	 * Read mmu_invalidate_seq so that KVM can detect if the results of
503  	 * vma_lookup() or __kvm_faultin_pfn() become stale prior to acquiring
504  	 * kvm->mmu_lock.
505  	 *
506  	 * Rely on mmap_read_unlock() for an implicit smp_rmb(), which pairs
507  	 * with the smp_wmb() in kvm_mmu_invalidate_end().
508  	 */
509  	mmu_seq = kvm->mmu_invalidate_seq;
510  	mmap_read_unlock(current->mm);
511  
512  	if (vma_pagesize != PUD_SIZE &&
513  	    vma_pagesize != PMD_SIZE &&
514  	    vma_pagesize != PAGE_SIZE) {
515  		kvm_err("Invalid VMA page size 0x%lx\n", vma_pagesize);
516  		return -EFAULT;
517  	}
518  
519  	hfn = __kvm_faultin_pfn(memslot, gfn, is_write ? FOLL_WRITE : 0,
520  				&writable, &page);
521  	if (hfn == KVM_PFN_ERR_HWPOISON) {
522  		send_sig_mceerr(BUS_MCEERR_AR, (void __user *)hva,
523  				vma_pageshift, current);
524  		return 0;
525  	}
526  	if (is_error_noslot_pfn(hfn))
527  		return -EFAULT;
528  
529  	/*
530  	 * If logging is active then we allow writable pages only
531  	 * for write faults.
532  	 */
533  	if (logging && !is_write)
534  		writable = false;
535  
536  	spin_lock(&kvm->mmu_lock);
537  
538  	if (mmu_invalidate_retry(kvm, mmu_seq))
539  		goto out_unlock;
540  
541  	/* Check if we are backed by a THP and thus use block mapping if possible */
542  	if (vma_pagesize == PAGE_SIZE)
543  		vma_pagesize = transparent_hugepage_adjust(kvm, memslot, hva, &hfn, &gpa);
544  
545  	if (writable) {
546  		mark_page_dirty_in_slot(kvm, memslot, gfn);
547  		ret = kvm_riscv_gstage_map_page(&gstage, pcache, gpa, hfn << PAGE_SHIFT,
548  						vma_pagesize, false, true, out_map);
549  	} else {
550  		ret = kvm_riscv_gstage_map_page(&gstage, pcache, gpa, hfn << PAGE_SHIFT,
551  						vma_pagesize, true, true, out_map);
552  	}
553  
554  	if (ret)
555  		kvm_err("Failed to map in G-stage\n");
556  
557  out_unlock:
558  	kvm_release_faultin_page(kvm, page, ret && ret != -EEXIST, writable);
559  	spin_unlock(&kvm->mmu_lock);
560  	return ret;
561  }

