423  static unsigned long transparent_hugepage_adjust(struct kvm *kvm, 						 struct kvm_memory_slot *memslot, 						 unsigned long hva, 						 kvm_pfn_t *hfnp, gpa_t *gpa)  {
424  	kvm_pfn_t hfn = *hfnp;
425  
426  	/*
427  	 * Make sure the adjustment is done only for THP pages. Also make
428  	 * sure that the HVA and GPA are sufficiently aligned and that the
429  	 * block map is contained within the memslot.
430  	 */
431  	if (fault_supports_gstage_huge_mapping(memslot, hva)) {
432  		int sz;
433  
434  		sz = get_hva_mapping_size(kvm, hva);
435  		if (sz < PMD_SIZE)
