363  static int handle_scalar_misaligned_load(struct pt_regs *regs)  {
364  	union reg_data val;
365  	unsigned long epc = regs->epc;
366  	unsigned long insn;
367  	unsigned long addr = regs->badaddr;
368  	int fp = 0, shift = 0, len = 0;
369  
370  	perf_sw_event(PERF_COUNT_SW_ALIGNMENT_FAULTS, 1, regs, addr);
371  
372  	*this_cpu_ptr(&misaligned_access_speed) = RISCV_HWPROBE_MISALIGNED_SCALAR_EMULATED;
373  
374  	if (!unaligned_enabled)
375  		return -1;
376  
377  	if (user_mode(regs) && (current->thread.align_ctl & PR_UNALIGN_SIGBUS))
378  		return -1;
379  
380  	if (get_insn(regs, epc, &insn))
381  		return -1;
382  
383  	regs->epc = 0;
384  
385  	if ((insn & INSN_MASK_LW) == INSN_MATCH_LW) {
386  		len = 4;
387  		shift = 8 * (sizeof(unsigned long) - len);
388  #if defined(CONFIG_64BIT)
389  	} else if ((insn & INSN_MASK_LD) == INSN_MATCH_LD) {
390  		len = 8;
391  		shift = 8 * (sizeof(unsigned long) - len);
392  	} else if ((insn & INSN_MASK_LWU) == INSN_MATCH_LWU) {
