419  static void __init riscv_resolve_isa(unsigned long *source_isa, 				     unsigned long *resolved_isa, unsigned long *this_hwcap, 				     unsigned long *isa2hwcap)  {
420  	bool loop;
421  	const struct riscv_isa_ext_data *ext;
422  	DECLARE_BITMAP(prev_resolved_isa, RISCV_ISA_EXT_MAX);
423  	int max_loop_count = riscv_isa_ext_count, ret;
424  	unsigned int bit;
425  
426  	do {
427  		loop = false;
428  		if (max_loop_count-- < 0) {
429  			pr_err("Failed to reach a stable ISA state\n");
430  			return;
431  		}
432  		bitmap_copy(prev_resolved_isa, resolved_isa, RISCV_ISA_EXT_MAX);
433  		for_each_set_bit(bit, source_isa, RISCV_ISA_EXT_MAX) {
434  			ext = riscv_get_isa_ext_data(bit);
435  			if (!ext)
436  				continue;
437  
438  			if (ext->validate) {
439  				ret = ext->validate(ext, resolved_isa);
440  				if (ret == -EPROBE_DEFER) {
441  					loop = true;
442  					continue;
443  				} else if (ret) {
444  					/* Disable the extension entirely */
445  					clear_bit(ext->id, source_isa);
446  					continue;
447  				}
448  			}
449  
450  			set_bit(ext->id, resolved_isa);
451  			/* No need to keep it in source isa now that it is enabled */
452  			clear_bit(ext->id, source_isa);
453  
454  			/* Single letter extensions get set in hwcap */
455  			if (ext->id < RISCV_ISA_EXT_BASE)
456  				*this_hwcap |= isa2hwcap[ext->id];
457  		}
458  	} while (loop && memcmp(prev_resolved_isa, resolved_isa, sizeof(prev_resolved_isa)));
459  }

