657  int kvm_riscv_vcpu_pmu_ctr_cfg_match(struct kvm_vcpu *vcpu, unsigned long ctr_base, 				     unsigned long ctr_mask, unsigned long flags, 				     unsigned long eidx, u64 evtdata, 				     struct kvm_vcpu_sbi_return *retdata)  {
658  	int ctr_idx, sbiret = 0;
659  	long ret;
660  	bool is_fevent;
661  	unsigned long event_code;
662  	u32 etype = kvm_pmu_get_perf_event_type(eidx);
663  	struct kvm_pmu *kvpmu = vcpu_to_pmu(vcpu);
664  	struct kvm_pmc *pmc = NULL;
665  	struct perf_event_attr attr = {
666  		.type = etype,
667  		.size = sizeof(struct perf_event_attr),
668  		.pinned = true,
669  		.disabled = true,
670  		/*
671  		 * It should never reach here if the platform doesn't support the sscofpmf
672  		 * extension as mode filtering won't work without it.
673  		 */
674  		.exclude_host = true,
675  		.exclude_hv = true,
676  		.exclude_user = !!(flags & SBI_PMU_CFG_FLAG_SET_UINH),
677  		.exclude_kernel = !!(flags & SBI_PMU_CFG_FLAG_SET_SINH),
678  		.config1 = RISCV_PMU_CONFIG1_GUEST_EVENTS,
679  	};
680  
681  	if (kvm_pmu_validate_counter_mask(kvpmu, ctr_base, ctr_mask) < 0) {
682  		sbiret = SBI_ERR_INVALID_PARAM;
683  		goto out;
684  	}
685  
686  	event_code = get_event_code(eidx);
687  	is_fevent = kvm_pmu_is_fw_event(eidx);
688  	if (is_fevent && event_code >= SBI_PMU_FW_MAX) {
689  		sbiret = SBI_ERR_NOT_SUPPORTED;
690  		goto out;
691  	}
692  
693  	/*
694  	 * SKIP_MATCH flag indicates the caller is aware of the assigned counter
695  	 * for this event. Just do a sanity check if it already marked used.
696  	 */
697  	if (flags & SBI_PMU_CFG_FLAG_SKIP_MATCH) {
698  		if (!test_bit(ctr_base + __ffs(ctr_mask), kvpmu->pmc_in_use)) {
699  			sbiret = SBI_ERR_FAILURE;
700  			goto out;
701  		}
702  		ctr_idx = ctr_base + __ffs(ctr_mask);
703  	} else  {
704  		ctr_idx = pmu_get_pmc_index(kvpmu, eidx, ctr_base, ctr_mask);
705  		if (ctr_idx < 0) {
706  			sbiret = SBI_ERR_NOT_SUPPORTED;
707  			goto out;
708  		}
709  	}
710  
711  	pmc = &kvpmu->pmc[ctr_idx];
712  	pmc->idx = ctr_idx;
713  
714  	if (is_fevent) {
715  		if (flags & SBI_PMU_CFG_FLAG_AUTO_START)
716  			kvpmu->fw_event[event_code].started = true;
717  	} else {
718  		ret = kvm_pmu_create_perf_event(pmc, &attr, flags, eidx, evtdata);
719  		if (ret) {
720  			sbiret = SBI_ERR_NOT_SUPPORTED;
721  			goto out;
722  		}
723  	}
724  
725  	set_bit(ctr_idx, kvpmu->pmc_in_use);
726  	pmc->event_idx = eidx;
727  	retdata->out_val = ctr_idx;
728  out:
729  	retdata->err_val = sbiret;
730  
731  	return 0;
732  }

