117  static long __restore_v_state(struct pt_regs *regs, void __user *sc_vec)  {
118  	long err;
119  	struct __sc_riscv_v_state __user *state = sc_vec;
120  	void __user *datap;
121  
122  	/* Copy everything of __sc_riscv_v_state except datap. */
123  	err = __copy_from_user(&current->thread.vstate, &state->v_state,
124  			       offsetof(struct __riscv_v_ext_state, datap));
125  	if (unlikely(err))
126  		return err;
127  
128  	/* Copy the pointer datap itself. */
129  	err = __get_user(datap, &state->v_state.datap);
130  	if (unlikely(err))
131  		return err;
132  	/*
133  	 * Copy the whole vector content from user space datap. Use
134  	 * copy_from_user to prevent information leak.
135  	 */
136  	err = copy_from_user(current->thread.vstate.datap, datap, riscv_v_vsize);
137  	if (unlikely(err))
138  		return err;
139  
140  	riscv_v_vstate_set_restore(current, regs);
141  
142  	return err;
143  }

117  static long __restore_v_state(struct pt_regs *regs, void __user *sc_vec)  {
118  	long err;
119  	struct __sc_riscv_v_state __user *state = sc_vec;
120  	void __user *datap;
121  
122  	/*
123  	 * Mark the vstate as clean prior performing the actual copy,
124  	 * to avoid getting the vstate incorrectly clobbered by the
125  	 *  discarded vector state.
126  	 */
127  	riscv_v_vstate_set_restore(current, regs);
128  
129  	/* Copy everything of __sc_riscv_v_state except datap. */
130  	err = __copy_from_user(&current->thread.vstate, &state->v_state,
131  			       offsetof(struct __riscv_v_ext_state, datap));
132  	if (unlikely(err))
133  		return err;
134  
135  	/* Copy the pointer datap itself. */
136  	err = __get_user(datap, &state->v_state.datap);
137  	if (unlikely(err))
138  		return err;
139  	/*
140  	 * Copy the whole vector content from user space datap. Use
141  	 * copy_from_user to prevent information leak.
142  	 */
143  	return copy_from_user(current->thread.vstate.datap, datap, riscv_v_vsize);
144  }

905  int kvm_riscv_vcpu_aia_imsic_rmw(struct kvm_vcpu *vcpu, unsigned long isel, 				 unsigned long *val, unsigned long new_val, 				 unsigned long wr_mask)  {
906  	u32 topei;
907  	struct imsic_mrif_eix *eix;
908  	int r, rc = KVM_INSN_CONTINUE_NEXT_SEPC;
909  	struct imsic *imsic = vcpu->arch.aia_context.imsic_state;
910  
911  	if (isel == KVM_RISCV_AIA_IMSIC_TOPEI) {
912  		/* Read pending and enabled interrupt with highest priority */
913  		topei = imsic_mrif_topei(imsic->swfile, imsic->nr_eix,
914  					 imsic->nr_msis);
915  		if (val)
916  			*val = topei;
917  
918  		/* Writes ignore value and clear top pending interrupt */
919  		if (topei && wr_mask) {
920  			topei >>= TOPEI_ID_SHIFT;
921  			if (topei) {
922  				eix = &imsic->swfile->eix[topei /
923  							  BITS_PER_TYPE(u64)];
924  				clear_bit(topei & (BITS_PER_TYPE(u64) - 1),
925  					  eix->eip);
926  			}
927  		}
928  	} else {
929  		r = imsic_mrif_rmw(imsic->swfile, imsic->nr_eix, isel,
930  				   val, new_val, wr_mask);
931  		/* Forward unknown IMSIC register to user-space */
932  		if (r)
933  			rc = (r == -ENOENT) ? 0 : KVM_INSN_ILLEGAL_TRAP;
934  	}
935  
936  	if (wr_mask)
937  		imsic_swfile_extirq_update(vcpu);
938  
939  	return rc;
940  }

