129  static void aplic_write_pending(struct aplic *aplic, u32 irq, bool pending)  {
130  	unsigned long flags, sm;
131  	struct aplic_irq *irqd;
132  
133  	if (!irq || aplic->nr_irqs <= irq)
134  		return;
135  	irqd = &aplic->irqs[irq];
136  
137  	raw_spin_lock_irqsave(&irqd->lock, flags);
138  
139  	sm = irqd->sourcecfg & APLIC_SOURCECFG_SM_MASK;
140  	if (!pending &&
141  	    ((sm == APLIC_SOURCECFG_SM_LEVEL_HIGH) ||
142  	     (sm == APLIC_SOURCECFG_SM_LEVEL_LOW)))
143  		goto skip_write_pending;
144  
145  	if (pending)
146  		irqd->state |= APLIC_IRQ_STATE_PENDING;
147  	else
148  		irqd->state &= ~APLIC_IRQ_STATE_PENDING;
149  
150  skip_write_pending:
151  	raw_spin_unlock_irqrestore(&irqd->lock, flags);
152  }

129  static void aplic_write_pending(struct aplic *aplic, u32 irq, bool pending)  {
130  	unsigned long flags, sm;
131  	struct aplic_irq *irqd;
132  
133  	if (!irq || aplic->nr_irqs <= irq)
134  		return;
135  	irqd = &aplic->irqs[irq];
136  
137  	raw_spin_lock_irqsave(&irqd->lock, flags);
138  
139  	sm = irqd->sourcecfg & APLIC_SOURCECFG_SM_MASK;
140  	if (sm == APLIC_SOURCECFG_SM_INACTIVE)
141  		goto skip_write_pending;
142  
143  	if (sm == APLIC_SOURCECFG_SM_LEVEL_HIGH ||
144  	    sm == APLIC_SOURCECFG_SM_LEVEL_LOW) {
145  		if (!pending)
146  			goto skip_write_pending;
147  		if ((irqd->state & APLIC_IRQ_STATE_INPUT) &&
148  		    sm == APLIC_SOURCECFG_SM_LEVEL_LOW)
149  			goto skip_write_pending;
150  		if (!(irqd->state & APLIC_IRQ_STATE_INPUT) &&
151  		    sm == APLIC_SOURCECFG_SM_LEVEL_HIGH)
152  			goto skip_write_pending;
153  	}
154  
155  	if (pending)
156  		irqd->state |= APLIC_IRQ_STATE_PENDING;
157  	else
158  		irqd->state &= ~APLIC_IRQ_STATE_PENDING;
159  
160  skip_write_pending:
161  	raw_spin_unlock_irqrestore(&irqd->lock, flags);
162  }

332  static void make_xfence_request(struct kvm *kvm, 				unsigned long hbase, unsigned long hmask, 				unsigned int req, unsigned int fallback_req, 				const struct kvm_riscv_hfence *data)  {
333  	unsigned long i;
334  	struct kvm_vcpu *vcpu;
335  	unsigned int actual_req = req;
336  	DECLARE_BITMAP(vcpu_mask, KVM_MAX_VCPUS);
337  
338  	bitmap_zero(vcpu_mask, KVM_MAX_VCPUS);
339  	kvm_for_each_vcpu(i, vcpu, kvm) {
340  		if (hbase != -1UL) {
341  			if (vcpu->vcpu_id < hbase)
342  				continue;
343  			if (!(hmask & (1UL << (vcpu->vcpu_id - hbase))))
344  				continue;
345  		}
346  
347  		bitmap_set(vcpu_mask, i, 1);
348  
349  		if (!data || !data->type)
350  			continue;
351  
352  		/*
353  		 * Enqueue hfence data to VCPU hfence queue. If we don't
354  		 * have space in the VCPU hfence queue then fallback to
355  		 * a more conservative hfence request.
356  		 */
357  		if (!vcpu_hfence_enqueue(vcpu, data))
358  			actual_req = fallback_req;
359  	}
360  
361  	kvm_make_vcpus_request_mask(kvm, actual_req, vcpu_mask);
362  }

