223  void handle_page_fault(struct pt_regs *regs)  {
224  	struct task_struct *tsk;
225  	struct vm_area_struct *vma;
226  	struct mm_struct *mm;
227  	unsigned long addr, cause;
228  	unsigned int flags = FAULT_FLAG_DEFAULT;
229  	int code = SEGV_MAPERR;
230  	vm_fault_t fault;
231  
232  	cause = regs->cause;
233  	addr = regs->badaddr;
234  
235  	tsk = current;
236  	mm = tsk->mm;
237  
238  	if (kprobe_page_fault(regs, cause))
239  		return;
240  
241  	/*
242  	 * Fault-in kernel-space virtual memory on-demand.
243  	 * The 'reference' page table is init_mm.pgd.
244  	 *
245  	 * NOTE! We MUST NOT take any locks for this case. We may
246  	 * be in an interrupt or a critical region, and should
247  	 * only copy the information from the master page table,
248  	 * nothing more.
249  	 */
250  	if ((!IS_ENABLED(CONFIG_MMU) || !IS_ENABLED(CONFIG_64BIT)) &&
251  	    unlikely(addr >= VMALLOC_START && addr < VMALLOC_END)) {
252  		vmalloc_fault(regs, code, addr);
253  		return;
254  	}
255  
256  	/* Enable interrupts if they were enabled in the parent context. */
257  	if (!regs_irqs_disabled(regs))
258  		local_irq_enable();
259  
260  	/*
261  	 * If we're in an interrupt, have no user context, or are running
262  	 * in an atomic region, then we must not take the fault.
263  	 */
264  	if (unlikely(faulthandler_disabled() || !mm)) {
265  		tsk->thread.bad_cause = cause;
266  		no_context(regs, addr);
267  		return;
268  	}
269  
270  	if (user_mode(regs))
271  		flags |= FAULT_FLAG_USER;
272  
273  	if (!user_mode(regs) && addr < TASK_SIZE && unlikely(!(regs->status & SR_SUM))) {
274  		if (fixup_exception(regs))
275  			return;
276  
277  		die_kernel_fault("access to user memory without uaccess routines", addr, regs);
278  	}
279  
280  	perf_sw_event(PERF_COUNT_SW_PAGE_FAULTS, 1, regs, addr);
281  
282  	if (cause == EXC_STORE_PAGE_FAULT)
283  		flags |= FAULT_FLAG_WRITE;
284  	else if (cause == EXC_INST_PAGE_FAULT)
285  		flags |= FAULT_FLAG_INSTRUCTION;
286  	if (!(flags & FAULT_FLAG_USER))
287  		goto lock_mmap;
288  
289  	vma = lock_vma_under_rcu(mm, addr);
290  	if (!vma)
291  		goto lock_mmap;
292  
293  	if (unlikely(access_error(cause, vma))) {
294  		vma_end_read(vma);
295  		count_vm_vma_lock_event(VMA_LOCK_SUCCESS);
296  		tsk->thread.bad_cause = cause;
297  		bad_area_nosemaphore(regs, SEGV_ACCERR, addr);
298  		return;
299  	}
300  
301  	fault = handle_mm_fault(vma, addr, flags | FAULT_FLAG_VMA_LOCK, regs);
302  	if (!(fault & (VM_FAULT_RETRY | VM_FAULT_COMPLETED)))
303  		vma_end_read(vma);
304  
305  	if (!(fault & VM_FAULT_RETRY)) {
306  		count_vm_vma_lock_event(VMA_LOCK_SUCCESS);
307  		goto done;
308  	}
309  	count_vm_vma_lock_event(VMA_LOCK_RETRY);
310  	if (fault & VM_FAULT_MAJOR)
311  		flags |= FAULT_FLAG_TRIED;
312  
313  	if (fault_signal_pending(fault, regs)) {
314  		if (!user_mode(regs))
315  			no_context(regs, addr);
316  		return;
317  	}
318  lock_mmap:
319  
320  retry:
321  	vma = lock_mm_and_find_vma(mm, addr, regs);
322  	if (unlikely(!vma)) {
323  		tsk->thread.bad_cause = cause;
324  		bad_area_nosemaphore(regs, code, addr);
325  		return;
326  	}
327  
328  	/*
329  	 * Ok, we have a good vm_area for this memory access, so
330  	 * we can handle it.
331  	 */
332  	code = SEGV_ACCERR;
333  
334  	if (unlikely(access_error(cause, vma))) {
335  		tsk->thread.bad_cause = cause;
336  		bad_area(regs, mm, code, addr);
337  		return;
338  	}
339  
340  	/*
341  	 * If for any reason at all we could not handle the fault,
342  	 * make sure we exit gracefully rather than endlessly redo
343  	 * the fault.
344  	 */
345  	fault = handle_mm_fault(vma, addr, flags, regs);
346  
347  	/*
348  	 * If we need to retry but a fatal signal is pending, handle the
349  	 * signal first. We do not need to release the mmap_lock because it
350  	 * would already be released in __lock_page_or_retry in mm/filemap.c.
351  	 */
352  	if (fault_signal_pending(fault, regs)) {
353  		if (!user_mode(regs))
354  			no_context(regs, addr);
355  		return;
356  	}
357  
358  	/* The fault is fully completed (including releasing mmap lock) */
359  	if (fault & VM_FAULT_COMPLETED)
360  		return;
361  
362  	if (unlikely(fault & VM_FAULT_RETRY)) {
363  		flags |= FAULT_FLAG_TRIED;
364  
365  		/*
366  		 * No need to mmap_read_unlock(mm) as we would
367  		 * have already released it in __lock_page_or_retry
368  		 * in mm/filemap.c.
369  		 */
370  		goto retry;
371  	}
372  
373  	mmap_read_unlock(mm);
374  
375  done:
376  	if (unlikely(fault & VM_FAULT_ERROR)) {
377  		tsk->thread.bad_cause = cause;
378  		mm_fault_error(regs, addr, fault);
379  		return;
380  	}
381  	return;
382  }

