262  int kvm_arch_prepare_memory_region(struct kvm *kvm, 				const struct kvm_memory_slot *old, 				struct kvm_memory_slot *new, 				enum kvm_mr_change change)  {
263  	hva_t hva, reg_end, size;
264  	bool writable;
265  	int ret = 0;
266  
267  	if (change != KVM_MR_CREATE && change != KVM_MR_MOVE &&
268  			change != KVM_MR_FLAGS_ONLY)
269  		return 0;
270  
271  	/*
272  	 * Prevent userspace from creating a memory region outside of the GPA
273  	 * space addressable by the KVM guest GPA space.
274  	 */
275  	if ((new->base_gfn + new->npages) >=
276  	     kvm_riscv_gstage_gpa_size(kvm->arch.pgd_levels) >> PAGE_SHIFT)
277  		return -EFAULT;
278  
279  	hva = new->userspace_addr;
280  	size = new->npages << PAGE_SHIFT;
281  	reg_end = hva + size;
282  	writable = !(new->flags & KVM_MEM_READONLY);
283  
284  	mmap_read_lock(current->mm);
285  
286  	/*
287  	 * A memory region could potentially cover multiple VMAs, and
288  	 * any holes between them, so iterate over all of them.
289  	 *
290  	 *     +--------------------------------------------+
291  	 * +---------------+----------------+   +----------------+
292  	 * |   : VMA 1     |      VMA 2     |   |    VMA 3  :    |
293  	 * +---------------+----------------+   +----------------+
294  	 *     |               memory region                |
295  	 *     +--------------------------------------------+
296  	 */
297  	do {
298  		struct vm_area_struct *vma;
299  		hva_t vm_end;
300  
301  		vma = find_vma_intersection(current->mm, hva, reg_end);
302  		if (!vma)
303  			break;
304  
305  		/*
306  		 * Mapping a read-only VMA is only allowed if the
307  		 * memory region is configured as read-only.
308  		 */
309  		if (writable && !(vma->vm_flags & VM_WRITE)) {
310  			ret = -EPERM;
311  			break;
312  		}
313  
314  		/* Take the intersection of this VMA with the memory region */
315  		vm_end = min(reg_end, vma->vm_end);
316  
317  		if (vma->vm_flags & VM_PFNMAP) {
318  			/* IO region dirty page logging not allowed */
319  			if (new->flags & KVM_MEM_LOG_DIRTY_PAGES) {
320  				ret = -EINVAL;
321  				goto out;
322  			}
323  		}
324  		hva = vm_end;
325  	} while (hva < reg_end);
326  
327  out:
328  	mmap_read_unlock(current->mm);
329  	return ret;
330  }

