39  		} else {
40  			pr_warn("KVM: No free entry in NACL shared memory\n");
41  			return;
42  		}
43  	}
44  
45  	entp = shmem + SBI_NACL_SHMEM_HFENCE_ENTRY_CONFIG(i);
46  	*entp = cpu_to_lelong(control);
47  	entp = shmem + SBI_NACL_SHMEM_HFENCE_ENTRY_PNUM(i);
48  	*entp = cpu_to_lelong(page_num);
49  	entp = shmem + SBI_NACL_SHMEM_HFENCE_ENTRY_PCOUNT(i);
50  	*entp = cpu_to_lelong(page_count);
51  }

573  void kvm_riscv_aia_enable(void)  {
574  	if (!kvm_riscv_aia_available())
575  		return;
576  
577  	csr_write(CSR_HVICTL, aia_hvictl_value(false));
578  	csr_write(CSR_HVIPRIO1, 0x0);
579  	csr_write(CSR_HVIPRIO2, 0x0);
580  #ifdef CONFIG_32BIT
581  	csr_write(CSR_HVIPH, 0x0);
582  	csr_write(CSR_HIDELEGH, 0x0);
583  	csr_write(CSR_HVIPRIO1H, 0x0);
584  	csr_write(CSR_HVIPRIO2H, 0x0);
585  #endif
586  
