182  static int kvm_sbi_ext_sta_set_reg(struct kvm_vcpu *vcpu, unsigned long reg_num, 				   unsigned long reg_size, const void *reg_val)  {
183  	unsigned long value;
184  
185  	if (reg_size != sizeof(unsigned long))
186  		return -EINVAL;
187  	value = *(const unsigned long *)reg_val;
188  
189  	switch (reg_num) {
190  	case KVM_REG_RISCV_SBI_STA_REG(shmem_lo):
191  		if (IS_ENABLED(CONFIG_32BIT)) {
192  			gpa_t hi = upper_32_bits(vcpu->arch.sta.shmem);
193  
194  			vcpu->arch.sta.shmem = value;
195  			vcpu->arch.sta.shmem |= hi << 32;
196  		} else {
197  			vcpu->arch.sta.shmem = value;
198  		}
199  		break;
200  	case KVM_REG_RISCV_SBI_STA_REG(shmem_hi):
201  		if (IS_ENABLED(CONFIG_32BIT)) {
202  			gpa_t lo = lower_32_bits(vcpu->arch.sta.shmem);
203  
204  			vcpu->arch.sta.shmem = ((gpa_t)value << 32);
205  			vcpu->arch.sta.shmem |= lo;
206  		} else if (value != 0) {
207  			return -EINVAL;
208  		}
209  		break;
210  	default:
211  		return -ENOENT;
212  	}
213  
214  	return 0;
215  }

182  static int kvm_sbi_ext_sta_set_reg(struct kvm_vcpu *vcpu, unsigned long reg_num, 				   unsigned long reg_size, const void *reg_val)  {
183  	unsigned long value;
184  	gpa_t new_shmem = INVALID_GPA;
185  
186  	if (reg_size != sizeof(unsigned long))
187  		return -EINVAL;
188  	value = *(const unsigned long *)reg_val;
189  
190  	switch (reg_num) {
191  	case KVM_REG_RISCV_SBI_STA_REG(shmem_lo):
192  		if (IS_ENABLED(CONFIG_32BIT)) {
193  			gpa_t hi = upper_32_bits(vcpu->arch.sta.shmem);
194  
195  			new_shmem = value;
196  			new_shmem |= hi << 32;
197  		} else {
198  			new_shmem = value;
199  		}
200  		break;
201  	case KVM_REG_RISCV_SBI_STA_REG(shmem_hi):
202  		if (IS_ENABLED(CONFIG_32BIT)) {
203  			gpa_t lo = lower_32_bits(vcpu->arch.sta.shmem);
204  
205  			new_shmem = ((gpa_t)value << 32);
206  			new_shmem |= lo;
207  		} else if (value != 0) {
208  			return -EINVAL;
209  		}
210  		break;
211  	default:
212  		return -ENOENT;
213  	}
214  
215  	if (new_shmem != INVALID_GPA && !IS_ALIGNED(new_shmem, 64))
216  		return -EINVAL;
217  
218  	vcpu->arch.sta.shmem = new_shmem;
219  
220  	return 0;
221  }

 80  int populate_cache_leaves(unsigned int cpu)  {
 81  	struct cpu_cacheinfo *this_cpu_ci = get_cpu_cacheinfo(cpu);
 82  	struct cacheinfo *this_leaf = this_cpu_ci->info_list;
 83  	struct device_node *np, *prev;
 84  	int levels = 1, level = 1;
 85  
 86  	if (!acpi_disabled) {
 87  		int ret, fw_levels, split_levels;
 88  
 89  		ret = acpi_get_cache_info(cpu, &fw_levels, &split_levels);
 90  		if (ret)
 91  			return ret;
 92  
 93  		BUG_ON((split_levels > fw_levels) ||
 94  		       (split_levels + fw_levels > this_cpu_ci->num_leaves));
 95  
 96  		for (; level <= this_cpu_ci->num_levels; level++) {
 97  			if (level <= split_levels) {
 98  				ci_leaf_init(this_leaf++, CACHE_TYPE_DATA, level);
 99  				ci_leaf_init(this_leaf++, CACHE_TYPE_INST, level);
100  			} else {
101  				ci_leaf_init(this_leaf++, CACHE_TYPE_UNIFIED, level);
102  			}
103  		}
104  		return 0;
105  	}
106  
107  	np = of_cpu_device_node_get(cpu);
108  	if (!np)
109  		return -ENOENT;
110  
111  	if (of_property_read_bool(np, "cache-size"))
112  		ci_leaf_init(this_leaf++, CACHE_TYPE_UNIFIED, level);
113  	if (of_property_read_bool(np, "i-cache-size"))
114  		ci_leaf_init(this_leaf++, CACHE_TYPE_INST, level);
115  	if (of_property_read_bool(np, "d-cache-size"))
116  		ci_leaf_init(this_leaf++, CACHE_TYPE_DATA, level);
117  
118  	prev = np;
119  	while ((np = of_find_next_cache_node(np))) {
120  		of_node_put(prev);
121  		prev = np;
122  		if (!of_device_is_compatible(np, "cache"))
123  			break;
124  		if (of_property_read_u32(np, "cache-level", &level))
125  			break;
126  		if (level <= levels)
127  			break;
128  		if (of_property_read_bool(np, "cache-size"))
129  			ci_leaf_init(this_leaf++, CACHE_TYPE_UNIFIED, level);
130  		if (of_property_read_bool(np, "i-cache-size"))
131  			ci_leaf_init(this_leaf++, CACHE_TYPE_INST, level);
132  		if (of_property_read_bool(np, "d-cache-size"))
133  			ci_leaf_init(this_leaf++, CACHE_TYPE_DATA, level);
134  		levels = level;
135  	}
136  	of_node_put(np);
137  
138  	return 0;
139  }

