153  void __noreturn machine_kexec(struct kimage *image)  {
154  	struct kimage_arch *internal = &image->arch;
155  	unsigned long jump_addr = (unsigned long) image->start;
156  	unsigned long first_ind_entry = (unsigned long) &image->head;
157  	unsigned long this_cpu_id = __smp_processor_id();
158  	unsigned long this_hart_id = cpuid_to_hartid_map(this_cpu_id);
159  	unsigned long fdt_addr = internal->fdt_addr;
160  	void *control_code_buffer = page_address(image->control_code_page);
161  	riscv_kexec_method kexec_method = NULL;
162  
163  #ifdef CONFIG_SMP
164  	WARN(smp_crash_stop_failed(),
165  		"Some CPUs may be stale, kdump will be unreliable.\n");
166  #endif
167  
168  	if (image->type != KEXEC_TYPE_CRASH)
169  		kexec_method = control_code_buffer;
170  	else
171  		kexec_method = (riscv_kexec_method) &riscv_kexec_norelocate;
172  
173  	pr_notice("Will call new kernel at %08lx from hart id %lx\n",
174  		  jump_addr, this_hart_id);
175  	pr_notice("FDT image at %08lx\n", fdt_addr);
176  
177  	/* Make sure the relocation code is visible to the hart */
178  	local_flush_icache_all();
179  
180  	/* Jump to the relocation code */
181  	pr_notice("Bye...\n");
182  	kexec_method(first_ind_entry, jump_addr, fdt_addr,
183  		     this_hart_id, kernel_map.va_pa_offset);
184  	unreachable();
185  }

390  static int aplic_mmio_read_offset(struct kvm *kvm, gpa_t off, u32 *val32)  {
391  	u32 i;
392  	struct aplic *aplic = kvm->arch.aia.aplic_state;
393  
394  	if ((off & 0x3) != 0)
395  		return -EOPNOTSUPP;
396  
397  	if (off == APLIC_DOMAINCFG) {
398  		*val32 = APLIC_DOMAINCFG_RDONLY |
399  			 aplic->domaincfg | APLIC_DOMAINCFG_DM;
400  	} else if ((off >= APLIC_SOURCECFG_BASE) &&
401  		 (off < (APLIC_SOURCECFG_BASE + (aplic->nr_irqs - 1) * 4))) {
402  		i = ((off - APLIC_SOURCECFG_BASE) >> 2) + 1;
403  		*val32 = aplic_read_sourcecfg(aplic, i);
404  	} else if ((off >= APLIC_SETIP_BASE) &&
405  		   (off < (APLIC_SETIP_BASE + aplic->nr_words * 4))) {
406  		i = (off - APLIC_SETIP_BASE) >> 2;
407  		*val32 = aplic_read_pending_word(aplic, i);
408  	} else if (off == APLIC_SETIPNUM) {
409  		*val32 = 0;
410  	} else if ((off >= APLIC_CLRIP_BASE) &&
411  		   (off < (APLIC_CLRIP_BASE + aplic->nr_words * 4))) {
412  		i = (off - APLIC_CLRIP_BASE) >> 2;
413  		*val32 = aplic_read_input_word(aplic, i);
414  	} else if (off == APLIC_CLRIPNUM) {
415  		*val32 = 0;
416  	} else if ((off >= APLIC_SETIE_BASE) &&
417  		   (off < (APLIC_SETIE_BASE + aplic->nr_words * 4))) {
418  		i = (off - APLIC_SETIE_BASE) >> 2;
419  		*val32 = aplic_read_enabled_word(aplic, i);
420  	} else if (off == APLIC_SETIENUM) {
421  		*val32 = 0;
422  	} else if ((off >= APLIC_CLRIE_BASE) &&
423  		   (off < (APLIC_CLRIE_BASE + aplic->nr_words * 4))) {
424  		*val32 = 0;
425  	} else if (off == APLIC_CLRIENUM) {
426  		*val32 = 0;
427  	} else if (off == APLIC_SETIPNUM_LE) {
428  		*val32 = 0;
429  	} else if (off == APLIC_SETIPNUM_BE) {
430  		*val32 = 0;
431  	} else if (off == APLIC_GENMSI) {
432  		*val32 = aplic->genmsi;
433  	} else if ((off >= APLIC_TARGET_BASE) &&
434  		   (off < (APLIC_TARGET_BASE + (aplic->nr_irqs - 1) * 4))) {
435  		i = ((off - APLIC_TARGET_BASE) >> 2) + 1;
436  		*val32 = aplic_read_target(aplic, i);
437  	} else
438  		return -ENODEV;
439  
