1394  static void __init preallocate_pgd_pages_range(unsigned long start, unsigned long end, 					       const char *area)  {
1395  	unsigned long addr;
1396  	const char *lvl;
1397  
1398  	for (addr = start; addr < end && addr >= start; addr = ALIGN(addr + 1, PGDIR_SIZE)) {
1399  		pgd_t *pgd = pgd_offset_k(addr);
1400  		p4d_t *p4d;
1401  		pud_t *pud;
1402  		pmd_t *pmd;
1403  
1404  		lvl = "p4d";
1405  		p4d = p4d_alloc(&init_mm, pgd, addr);
1406  		if (!p4d)
1407  			goto failed;
1408  
1409  		if (pgtable_l5_enabled)
1410  			continue;
1411  
1412  		lvl = "pud";
1413  		pud = pud_alloc(&init_mm, p4d, addr);
1414  		if (!pud)
1415  			goto failed;
1416  
1417  		if (pgtable_l4_enabled)
1418  			continue;
1419  
1420  		lvl = "pmd";
1421  		pmd = pmd_alloc(&init_mm, pud, addr);
1422  		if (!pmd)
1423  			goto failed;
1424  	}
1425  	return;
1426  
1427  failed:
1428  	/*
1429  	 * The pages have to be there now or they will be missing in
1430  	 * process page-tables later.
1431  	 */
1432  	panic("Failed to pre-allocate %s pages for %s area\n", lvl, area);
1433  }

