572  static int kvm_riscv_vcpu_get_reg_isa_ext(struct kvm_vcpu *vcpu, 					  const struct kvm_one_reg *reg)  {
573  	int rc;
574  	unsigned long __user *uaddr =
575  			(unsigned long __user *)(unsigned long)reg->addr;
576  	unsigned long reg_num = reg->id & ~(KVM_REG_ARCH_MASK |
577  					    KVM_REG_SIZE_MASK |
578  					    KVM_REG_RISCV_ISA_EXT);
579  	unsigned long reg_val, reg_subtype;
580  
581  	if (KVM_REG_SIZE(reg->id) != sizeof(unsigned long))
582  		return -EINVAL;
583  
584  	reg_subtype = reg_num & KVM_REG_RISCV_SUBTYPE_MASK;
585  	reg_num &= ~KVM_REG_RISCV_SUBTYPE_MASK;
586  
587  	reg_val = 0;
588  	switch (reg_subtype) {
589  	case KVM_REG_RISCV_ISA_SINGLE:
590  		rc = riscv_vcpu_get_isa_ext_single(vcpu, reg_num, &reg_val);
591  		break;
592  	case KVM_REG_RISCV_ISA_MULTI_EN:
593  	case KVM_REG_RISCV_ISA_MULTI_DIS:
594  		rc = riscv_vcpu_get_isa_ext_multi(vcpu, reg_num, &reg_val);
595  		if (!rc && reg_subtype == KVM_REG_RISCV_ISA_MULTI_DIS)
596  			reg_val = ~reg_val;
597  		break;
598  	default:
599  		rc = -ENOENT;
600  	}
601  	if (rc)
602  		return rc;
603  
604  	if (copy_to_user(uaddr, &reg_val, KVM_REG_SIZE(reg->id)))
605  		return -EFAULT;
606  
607  	return 0;
608  }

