737  void kvm_riscv_vcpu_aia_imsic_release(struct kvm_vcpu *vcpu)  {
738  	unsigned long flags;
739  	struct imsic_mrif tmrif;
740  	int old_vsfile_hgei, old_vsfile_cpu;
741  	struct imsic *imsic = vcpu->arch.aia_context.imsic_state;
742  
743  	if (!imsic)
744  		return;
745  
746  	/* Read and clear IMSIC VS-file details */
747  	write_lock_irqsave(&imsic->vsfile_lock, flags);
748  	old_vsfile_hgei = imsic->vsfile_hgei;
749  	old_vsfile_cpu = imsic->vsfile_cpu;
750  	imsic->vsfile_cpu = imsic->vsfile_hgei = -1;
751  	imsic->vsfile_va = NULL;
752  	imsic->vsfile_pa = 0;
753  	write_unlock_irqrestore(&imsic->vsfile_lock, flags);
754  
755  	/* Do nothing, if no IMSIC VS-file to release */
756  	if (old_vsfile_cpu < 0)
757  		return;
758  
759  	/*
760  	 * At this point, all interrupt producers are still using
761  	 * the old IMSIC VS-file so we first re-direct all interrupt
762  	 * producers.
763  	 */
764  
765  	/* Purge the G-stage mapping */
766  	kvm_riscv_mmu_iounmap(vcpu->kvm, vcpu->arch.aia_context.imsic_addr,
767  			      IMSIC_MMIO_PAGE_SZ);
768  
769  	/* TODO: Purge the IOMMU mapping ??? */
770  
771  	/*
772  	 * At this point, all interrupt producers have been re-directed
773  	 * to somewhere else so we move register state from the old IMSIC
774  	 * VS-file to the IMSIC SW-file.
775  	 */
776  
777  	/* Read and clear register state from old IMSIC VS-file */
778  	memset(&tmrif, 0, sizeof(tmrif));
779  	imsic_vsfile_read(old_vsfile_hgei, old_vsfile_cpu, imsic->nr_hw_eix,
780  			  true, &tmrif);
781  
782  	/* Update register state in IMSIC SW-file */
783  	imsic_swfile_update(vcpu, &tmrif);
784  
785  	/* Free-up old IMSIC VS-file */
786  	kvm_riscv_aia_free_hgei(old_vsfile_cpu, old_vsfile_hgei);
787  }

