369  static void imsic_vsfile_local_read(void *data)  {
370  	u32 i;
371  	struct imsic_mrif_eix *eix;
372  	struct imsic_vsfile_read_data *idata = data;
373  	struct imsic_mrif *mrif = idata->mrif;
374  	unsigned long new_hstatus, old_hstatus, old_vsiselect;
375  
376  	old_vsiselect = csr_read(CSR_VSISELECT);
377  	old_hstatus = csr_read(CSR_HSTATUS);
378  	new_hstatus = old_hstatus & ~HSTATUS_VGEIN;
379  	new_hstatus |= ((unsigned long)idata->hgei) << HSTATUS_VGEIN_SHIFT;
380  	csr_write(CSR_HSTATUS, new_hstatus);
381  
382  	/*
383  	 * We don't use imsic_mrif_atomic_xyz() functions to store
384  	 * values in MRIF because imsic_vsfile_read() is always called
385  	 * with pointer to temporary MRIF on stack.
386  	 */
387  
388  	if (idata->clear) {
389  		mrif->eidelivery = imsic_vs_csr_swap(IMSIC_EIDELIVERY, 0);
390  		mrif->eithreshold = imsic_vs_csr_swap(IMSIC_EITHRESHOLD, 0);
391  		for (i = 0; i < idata->nr_eix; i++) {
392  			eix = &mrif->eix[i];
393  			eix->eip[0] = imsic_eix_swap(IMSIC_EIP0 + i * 2, 0);
394  			eix->eie[0] = imsic_eix_swap(IMSIC_EIE0 + i * 2, 0);
395  #ifdef CONFIG_32BIT
396  			eix->eip[1] = imsic_eix_swap(IMSIC_EIP0 + i * 2 + 1, 0);
397  			eix->eie[1] = imsic_eix_swap(IMSIC_EIE0 + i * 2 + 1, 0);
398  #endif
399  		}
400  	} else {
401  		mrif->eidelivery = imsic_vs_csr_read(IMSIC_EIDELIVERY);
402  		mrif->eithreshold = imsic_vs_csr_read(IMSIC_EITHRESHOLD);
403  		for (i = 0; i < idata->nr_eix; i++) {
404  			eix = &mrif->eix[i];
405  			eix->eip[0] = imsic_eix_read(IMSIC_EIP0 + i * 2);
406  			eix->eie[0] = imsic_eix_read(IMSIC_EIE0 + i * 2);
407  #ifdef CONFIG_32BIT
408  			eix->eip[1] = imsic_eix_read(IMSIC_EIP0 + i * 2 + 1);
409  			eix->eie[1] = imsic_eix_read(IMSIC_EIE0 + i * 2 + 1);
410  #endif
411  		}
412  	}
413  
414  	csr_write(CSR_HSTATUS, old_hstatus);
415  	csr_write(CSR_VSISELECT, old_vsiselect);
416  }

