595  int kvm_riscv_vcpu_sbi_ecall(struct kvm_vcpu *vcpu, struct kvm_run *run)  {
596  	int ret = 1;
597  	bool next_sepc = true;
598  	struct kvm_cpu_context *cp = &vcpu->arch.guest_context;
599  	const struct kvm_vcpu_sbi_extension *sbi_ext;
600  	struct kvm_cpu_trap utrap = {0};
601  	struct kvm_vcpu_sbi_return sbi_ret = {
602  		.out_val = 0,
603  		.err_val = 0,
604  		.utrap = &utrap,
605  	};
606  	bool ext_is_v01 = false;
607  
608  	sbi_ext = kvm_vcpu_sbi_find_ext(vcpu, cp->a7);
609  	if (sbi_ext && sbi_ext->handler) {
610  #ifdef CONFIG_RISCV_SBI_V01
611  		if (cp->a7 >= SBI_EXT_0_1_SET_TIMER &&
612  		    cp->a7 <= SBI_EXT_0_1_SHUTDOWN)
613  			ext_is_v01 = true;
614  #endif
615  		ret = sbi_ext->handler(vcpu, run, &sbi_ret);
616  	} else {
617  		/* Return error for unsupported SBI calls */
618  		cp->a0 = SBI_ERR_NOT_SUPPORTED;
619  		goto ecall_done;
620  	}
621  
622  	/*
623  	 * When the SBI extension returns a Linux error code, it exits the ioctl
624  	 * loop and forwards the error to userspace.
625  	 */
626  	if (ret < 0) {
627  		next_sepc = false;
628  		goto ecall_done;
629  	}
630  
631  	/* Handle special error cases i.e trap, exit or userspace forward */
632  	if (sbi_ret.utrap->scause) {
633  		/* No need to increment sepc or exit ioctl loop */
634  		ret = 1;
635  		sbi_ret.utrap->sepc = cp->sepc;
636  		kvm_riscv_vcpu_trap_redirect(vcpu, sbi_ret.utrap);
637  		next_sepc = false;
638  		goto ecall_done;
639  	}
640  
641  	/* Exit ioctl loop or Propagate the error code the guest */
642  	if (sbi_ret.uexit) {
643  		next_sepc = false;
644  		ret = 0;
645  	} else {
646  		cp->a0 = sbi_ret.err_val;
647  		ret = 1;
648  	}
649  ecall_done:
650  	if (next_sepc)
651  		cp->sepc += 4;
652  	/* a1 should only be updated when we continue the ioctl loop */
653  	if (!ext_is_v01 && ret == 1)
654  		cp->a1 = sbi_ret.out_val;
655  
656  	return ret;
657  }

