548  static void imsic_vsfile_local_update(int vsfile_hgei, u32 nr_eix, 				      struct imsic_mrif *mrif)  {
549  	u32 i;
550  	struct imsic_mrif_eix *eix;
551  	unsigned long new_hstatus, old_hstatus, old_vsiselect;
552  
553  	/* We can only update if we have a HW IMSIC context */
554  	if (vsfile_hgei <= 0)
555  		return;
556  
557  	/*
558  	 * We don't use imsic_mrif_atomic_xyz() functions to read values
559  	 * from MRIF in this function because it is always called with
560  	 * pointer to temporary MRIF on stack.
561  	 */
562  
563  	old_vsiselect = csr_read(CSR_VSISELECT);
564  	old_hstatus = csr_read(CSR_HSTATUS);
565  	new_hstatus = old_hstatus & ~HSTATUS_VGEIN;
566  	new_hstatus |= ((unsigned long)vsfile_hgei) << HSTATUS_VGEIN_SHIFT;
567  	csr_write(CSR_HSTATUS, new_hstatus);
568  
569  	for (i = 0; i < nr_eix; i++) {
570  		eix = &mrif->eix[i];
571  		imsic_eix_set(IMSIC_EIP0 + i * 2, eix->eip[0]);
572  		imsic_eix_set(IMSIC_EIE0 + i * 2, eix->eie[0]);
573  #ifdef CONFIG_32BIT
574  		imsic_eix_set(IMSIC_EIP0 + i * 2 + 1, eix->eip[1]);
575  		imsic_eix_set(IMSIC_EIE0 + i * 2 + 1, eix->eie[1]);
576  #endif
577  	}
578  	imsic_vs_csr_write(IMSIC_EITHRESHOLD, mrif->eithreshold);
579  	imsic_vs_csr_write(IMSIC_EIDELIVERY, mrif->eidelivery);
580  
581  	csr_write(CSR_HSTATUS, old_hstatus);
582  	csr_write(CSR_VSISELECT, old_vsiselect);
583  }

