137  static int emit_addr(u8 rd, u64 addr, bool extra_pass, struct rv_jit_context *ctx)  {
138  	/*
139  	 * Use the ro_insns(RX) to calculate the offset as the BPF program will
140  	 * finally run from this memory region.
141  	 */
142  	u64 ip = (u64)(ctx->ro_insns + ctx->ninsns);
143  	s64 off = addr - ip;
144  	s64 upper = (off + (1 << 11)) >> 12;
145  	s64 lower = off & 0xfff;
146  
147  	if (extra_pass && !in_auipc_jalr_range(off)) {
148  		pr_err("bpf-jit: target offset 0x%llx is out of range\n", off);
149  		return -ERANGE;
150  	}
151  
152  	emit(rv_auipc(rd, upper), ctx);
153  	emit(rv_addi(rd, rd, lower), ctx);
154  	return 0;
155  }

