113  static bool in_auipc_jalr_range(s64 val)  {
114  	/*
115  	 * auipc+jalr can reach any signed PC-relative offset in the range
116  	 * [-2^31 - 2^11, 2^31 - 2^11).
117  	 */
118  	return (-(1L << 31) - (1L << 11)) <= val &&
119  		val < ((1L << 31) - (1L << 11));
120  }

