249  static void emit_bcc(u8 cond, u8 rd, u8 rs, int rvoff, 		     struct rv_jit_context *ctx)  {
250  	switch (cond) {
251  	case BPF_JEQ:
252  		emit(rv_beq(rd, rs, rvoff >> 1), ctx);
253  		return;
254  	case BPF_JGT:
255  		emit(rv_bltu(rs, rd, rvoff >> 1), ctx);
256  		return;
257  	case BPF_JLT:
258  		emit(rv_bltu(rd, rs, rvoff >> 1), ctx);
259  		return;
260  	case BPF_JGE:
261  		emit(rv_bgeu(rd, rs, rvoff >> 1), ctx);
262  		return;
263  	case BPF_JLE:
264  		emit(rv_bgeu(rs, rd, rvoff >> 1), ctx);
265  		return;
266  	case BPF_JNE:
267  		emit(rv_bne(rd, rs, rvoff >> 1), ctx);
268  		return;
269  	case BPF_JSGT:
270  		emit(rv_blt(rs, rd, rvoff >> 1), ctx);
271  		return;
272  	case BPF_JSLT:
273  		emit(rv_blt(rd, rs, rvoff >> 1), ctx);
274  		return;
275  	case BPF_JSGE:
276  		emit(rv_bge(rd, rs, rvoff >> 1), ctx);
277  		return;
278  	case BPF_JSLE:
279  		emit(rv_bge(rs, rd, rvoff >> 1), ctx);
280  	}
281  }

