225  static void __kprobes post_kprobe_handler(struct kprobe *cur, struct kprobe_ctlblk *kcb, struct pt_regs *regs)  {
226  	/* return addr restore if non-branching insn */
227  	if (cur->ainsn.api.restore != 0)
