 698  	if (pgd_val(pgdp[pgd_idx]) == 0) {
 699  		next_phys = alloc_pgd_next(va);
 700  		pgdp[pgd_idx] = pfn_pgd(PFN_DOWN(next_phys), PAGE_TABLE);
 701  		nextp = get_pgd_next_virt(next_phys);
 702  		memset(nextp, 0, PAGE_SIZE);
