1209  static void __init create_linear_mapping_page_table(void)  {
1210  	phys_addr_t start, end;
1211  	phys_addr_t kfence_pool __maybe_unused;
1212  	u64 i;
1213  
1214  #ifdef CONFIG_STRICT_KERNEL_RWX
1215  	phys_addr_t ktext_start = __pa_symbol(_start);
1216  	phys_addr_t ktext_size = __init_data_begin - _start;
1217  	phys_addr_t krodata_start = __pa_symbol(__start_rodata);
1218  	phys_addr_t krodata_size = _data - __start_rodata;
1219  
1220  	/* Isolate kernel text and rodata so they don't get mapped with a PUD */
1221  	memblock_mark_nomap(ktext_start,  ktext_size);
1222  	memblock_mark_nomap(krodata_start, krodata_size);
1223  #endif
1224  
1225  #ifdef CONFIG_KFENCE
1226  	/*
1227  	 *  kfence pool must be backed by PAGE_SIZE mappings, so allocate it
1228  	 *  before we setup the linear mapping so that we avoid using hugepages
1229  	 *  for this region.
1230  	 */
1231  	kfence_pool = memblock_phys_alloc(KFENCE_POOL_SIZE, PAGE_SIZE);
1232  	BUG_ON(!kfence_pool);
1233  
1234  	memblock_mark_nomap(kfence_pool, KFENCE_POOL_SIZE);
1235  	__kfence_pool = __va(kfence_pool);
1236  #endif
1237  
1238  	/* Map all memory banks in the linear mapping */
1239  	for_each_mem_range(i, &start, &end) {
1240  		if (start <= __pa(PAGE_OFFSET) &&
1241  		    __pa(PAGE_OFFSET) < end)
1242  			start = __pa(PAGE_OFFSET);
1243  
1244  		create_linear_mapping_range(start, end, 0, NULL);
1245  	}
1246  
1247  #ifdef CONFIG_STRICT_KERNEL_RWX
1248  	create_linear_mapping_range(ktext_start, ktext_start + ktext_size, 0, NULL);
1249  	create_linear_mapping_range(krodata_start, krodata_start + krodata_size, 0, NULL);
1250  
1251  	memblock_clear_nomap(ktext_start,  ktext_size);
1252  	memblock_clear_nomap(krodata_start, krodata_size);
1253  #endif
1254  
1255  #ifdef CONFIG_KFENCE
1256  	create_linear_mapping_range(kfence_pool, kfence_pool + KFENCE_POOL_SIZE, PAGE_SIZE, NULL);
1257  
1258  	memblock_clear_nomap(kfence_pool, KFENCE_POOL_SIZE);
1259  #endif
1260  }

